1	// types.mjs — shared value model mirroring what Python's yaml.safe_load() produces.
2	// All modules (resolver, parser, emitter) build on these classes.
3	// Pure ESM, no external imports, no RegExp, no JSON.
4	
5	export class YamlError extends Error {
6	  constructor(message) {
7	    super(message);
8	    this.name = 'YamlError';
9	  }
10	}
11	
12	// Python datetime.date
13	export class YamlDate {
14	  constructor(year, month, day) {
15	    this.year = year;     // int
16	    this.month = month;   // int 1-12
17	    this.day = day;       // int 1-31
18	  }
19	}
20	
21	// Python datetime.datetime. tzOffsetMinutes === null means "naive" (no timezone).
22	export class YamlDateTime {
23	  constructor(year, month, day, hour, minute, second, microsecond = 0, tzOffsetMinutes = null) {
24	    this.year = year;
25	    this.month = month;
26	    this.day = day;
27	    this.hour = hour;
28	    this.minute = minute;
29	    this.second = second;
30	    this.microsecond = microsecond;         // int 0..999999
31	    this.tzOffsetMinutes = tzOffsetMinutes; // int (minutes east of UTC) or null
32	  }
33	}
34	
35	// Python bytes produced by the !!binary constructor.
36	export class YamlBinary {
37	  constructor(bytes /* Uint8Array */) {
38	    this.bytes = bytes;
39	  }
40	}
41	
42	function padNum(n, width) {
43	  let s = String(n);
44	  while (s.length < width) s = '0' + s;
45	  return s;
46	}
47	
48	// 'YYYY-MM-DD HH:MM:SS[.ffffff][+HH:MM]' — Python datetime.isoformat(sep=' ')
49	export function dateTimeToString(dt) {
50	  let s = padNum(dt.year, 4) + '-' + padNum(dt.month, 2) + '-' + padNum(dt.day, 2);
51	  if (dt instanceof YamlDateTime) {
52	    s += ' ' + padNum(dt.hour, 2) + ':' + padNum(dt.minute, 2) + ':' + padNum(dt.second, 2);
53	    if (dt.microsecond !== 0) s += '.' + padNum(dt.microsecond, 6);
54	    if (dt.tzOffsetMinutes !== null) {
55	      const sign = dt.tzOffsetMinutes < 0 ? '-' : '+';
56	      const abs = Math.abs(dt.tzOffsetMinutes);
57	      s += sign + padNum(Math.floor(abs / 60), 2) + ':' + padNum(abs % 60, 2);
58	    }
59	  }
60	  return s;
61	}
62	
63	// Normalize a JS key the way a Python dict would treat it (True == 1 == 1.0,
64	// None distinct, etc.) so duplicate-key handling matches CPython semantics.
65	function normalizeKey(key) {
66	  if (key === null) return 'null:';
67	  if (typeof key === 'boolean') return 'num:' + (key ? 1 : 0);
68	  if (typeof key === 'number') return 'num:' + key;
69	  if (typeof key === 'bigint') return 'num:' + key.toString();
70	  if (typeof key === 'string') return 'str:' + key;
71	  if (key instanceof YamlDateTime) return 'dt:' + dateTimeToString(key);
72	  if (key instanceof YamlDate) return 'date:' + dateTimeToString(key);
73	  throw new YamlError('found unhashable key');
74	}
75	
76	// Insertion-ordered mapping with Python dict semantics: setting an existing
77	// key replaces the value but keeps the original key object and position.
78	export class YamlMap {
79	  constructor() {
80	    this._slots = new Map(); // normKey -> [origKey, value]
81	    this._order = [];        // normKeys in first-insertion order
82	  }
83	  set(key, value) {
84	    const norm = normalizeKey(key);
85	    if (this._slots.has(norm)) {
86	      this._slots.get(norm)[1] = value;
87	    } else {
88	      this._slots.set(norm, [key, value]);
89	      this._order.push(norm);
90	    }
91	  }
92	  get(key) {
93	    const slot = this._slots.get(normalizeKey(key));
94	    return slot ? slot[1] : undefined;
95	  }
96	  has(key) {
97	    return this._slots.has(normalizeKey(key));
98	  }
99	  get size() {
100	    return this._order.length;
101	  }
102	  // Array of [origKey, value] pairs in insertion order.
103	  entries() {
104	    return this._order.map((k) => this._slots.get(k));
105	  }
106	}
107	
108	// Python's sorted() comparison for mapping keys (yaml.dump sorts keys by
109	// default). Mixed incomparable types throw, like CPython's TypeError.
110	export function pythonKeyCompare(a, b) {
111	  const rank = (v) => {
112	    if (typeof v === 'boolean') return 0;
113	    if (typeof v === 'number' || typeof v === 'bigint') return 0;
114	    if (typeof v === 'string') return 1;
115	    if (v instanceof YamlDateTime) return 2;
116	    if (v instanceof YamlDate) return 3;
117	    if (v === null) return 4;
118	    return 5;
119	  };
120	  const ra = rank(a);
121	  const rb = rank(b);
122	  if (ra !== rb) throw new YamlError("'<' not supported between instances of mapping keys");
123	  if (ra === 0) {
124	    const na = typeof a === 'boolean' ? (a ? 1 : 0) : Number(a);
125	    const nb = typeof b === 'boolean' ? (b ? 1 : 0) : Number(b);
126	    return na < nb ? -1 : na > nb ? 1 : 0;
127	  }
128	  if (ra === 1) return a < b ? -1 : a > b ? 1 : 0;
129	  if (ra === 2 || ra === 3) {
130	    const sa = dateTimeToString(a);
131	    const sb = dateTimeToString(b);
132	    return sa < sb ? -1 : sa > sb ? 1 : 0;
133	  }
134	  return 0;
135	}

