import { resolvePlainScalar, resolveTaggedScalar } from '/output/resolver.mjs';
import { YamlDate, YamlDateTime, YamlBinary, dateTimeToString } from '/output/types.mjs';

function show(v) {
  if (v === null) return 'null';
  if (typeof v === 'bigint') return 'bigint:' + v.toString();
  if (typeof v === 'number') return 'num:' + String(v);
  if (typeof v === 'boolean') return 'bool:' + v;
  if (typeof v === 'string') return 'str:' + v;
  if (v instanceof YamlDateTime) return 'dt:' + dateTimeToString(v);
  if (v instanceof YamlDate) return 'date:' + dateTimeToString(v);
  if (v instanceof YamlBinary) return 'bin:' + Array.from(v.bytes).join(',');
  return '?';
}

const plain = ['0:30.5', '1:2:3:4', '0.5_0', '2_024-01-15', '2024-01-15T14:30:00.123456Z',
  '10_00', '.5_5', '+.INF', '9999-12-31 23:59:59.999999', '2024-01-15 14:30:00-0'];
for (const p of plain) {
  let r;
  try { r = show(resolvePlainScalar(p)); } catch (e) { r = 'ERROR ' + e.message; }
  console.log(p, '=>', r);
}
const tagged = [
  ['!!timestamp', '2024-01-15t14:30:00'], ['!!int', '1:60'], ['!!float', '1e'],
  ['!!binary', 'a G k ='], ['!!float', '1:60.5'], ['!!int', ':30'], ['!!float', ':30'],
  ['!!int', '0x'], ['!!float', '.'], ['!!int', '.'], ['!!bool', 'OFF'], ['!!null', ''],
];
for (const [t, v] of tagged) {
  let r;
  try { r = show(resolveTaggedScalar(t, v)); } catch (e) { r = 'ERROR ' + e.message; }
  console.log(t, JSON.stringify(v), '=>', r);
}

